    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 判断类型 ========== */
        function detectType(messageText) {
            if (messageText.indexOf('<档案清算>') !== -1) {
                return 'death';
            }
            if (messageText.indexOf('<回溯结算>') !== -1) {
                return 'rewind';
            }
            return null;
        }

        /* ========== 通用字段提取 ==========
         * 宽容匹配：标签支持多个别名（第一个命中的优先），值取到「|」或换行前。
         * 兼容同一行多个字段：| 个体: X | 终级: Y | 存活: Z |
         * 占位符清理：值整体形如 [xxx]（纯占位符包裹）时剥掉方括号，如 [角色名] → 角色名；
         * 值本身含括号内容（如 Lv.12 [圣骑士]）则保留原样。
         */
        function cleanBrackets(val) {
            var v = String(val || '').trim();
            if (/^\[[^\[\]]*\]$/.test(v)) return v.slice(1, -1).trim();
            return v;
        }
        function grabField(content, labels) {
            for (var i = 0; i < labels.length; i++) {
                var label = labels[i].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                var re = new RegExp(label + '\\s*[:：]\\s*([^|\\n]+)');
                var m = content.match(re);
                if (m && m[1] !== undefined && m[1].trim() !== '') {
                    return cleanBrackets(m[1]);
                }
            }
            return null;
        }

        /* ========== 解析档案清算 ========== */
        function parseDeathReport(messageText) {
            var result = {};
            var match = messageText.match(/<档案清算>([\s\S]*?)<\/档案清算>/);
            if (!match || !match[1]) return result;
            var content = match[1];

            var codeMatch = content.match(/\{推演代号[:：]\s*([^}]+)\}/);
            result.codename = codeMatch ? codeMatch[1].trim() : '陨落的命轨';

            // 多别名：与数据格式（个体/终级/存活/死因/世界线扰动/总评）对齐，
            // 同时兼容旧标签（陨落个体/最终等级/存活时长/致死原因/最终评价）
            result.name = grabField(content, ['个体', '陨落个体', '角色名']) || '未知';
            result.level = grabField(content, ['终级', '最终等级', '等级']) || '未知';
            result.duration = grabField(content, ['存活', '存活时长', '生存时长']) || '未知';
            result.cause = grabField(content, ['死因', '致死原因']) || '未知';
            result.disturbance = grabField(content, ['世界线扰动', '世界线影响', '世界扰动']) || '未对本源产生明显干涉';
            result.evaluation = grabField(content, ['总评', '最终评价']) || '';

            return result;
        }

        /* ========== 解析回溯结算 ========== */
        function parseRewindData(messageText) {
            var result = {};
            var match = messageText.match(/<回溯结算>([\s\S]*?)<\/回溯结算>/);
            if (!match || !match[1]) return result;
            var content = match[1];

            var subtitleMatch = content.match(/\{([^}]+)\}/);
            result.subtitle = subtitleMatch ? subtitleMatch[1].trim() : '法则干涉: 死亡回溯';

            result.trigger = grabField(content, ['触发者', '回溯者', '被回溯者']) || '未知';
            result.trauma = grabField(content, ['致死创伤记忆', '创伤记忆', '创伤']) || '未知';

            var timeMatch = content.match(/(?:时间回跃|回跃时间|时间回溯|回溯时间)[:：]\s*([^|\n]+)/);
            if (timeMatch) {
                var timeStr = timeMatch[1].trim();
                var parts = timeStr.split(/->|→/);
                if (parts.length === 2) {
                    result.timeFrom = parts[0].trim().replace(/^\[|\]$/g, '').trim();
                    result.timeTo = parts[1].trim().replace(/^\[|\]$/g, '').trim();
                } else {
                    result.timeFrom = timeStr.replace(/^\[|\]$/g, '').trim();
                    result.timeTo = '';
                }
            } else {
                result.timeFrom = '未知';
                result.timeTo = '未知';
            }

            result.dice = grabField(content, ['精神磨损判定', '磨损判定', '判定骰']) || '';
            result.result = grabField(content, ['判定结果', '结果']) || '';
            result.status = grabField(content, ['状态追加', '追加状态', '状态']) || '';

            return result;
        }

        /* ========== 渲染档案清算（方案A 卷宗文书） ========== */
        function renderDeath(data) {
            var html = '';
            html += '<div class="pA-panel pA-death">';
            html += '<span class="pA-corner tl"></span>';
            html += '<span class="pA-corner tr"></span>';
            html += '<span class="pA-corner bl"></span>';
            html += '<span class="pA-corner br"></span>';
            html += '<div class="pA-seal">殁</div>';

            html += '<div class="pA-head">';
            html += '<div class="pA-code">' + (data.codename || '陨落的命轨') + '</div>';
            html += '<div class="pA-title">命轨清算</div>';
            html += '<div class="pA-sub">ARCHIVE · 陨落卷宗</div>';
            html += '</div>';

            html += '<div class="pA-hairline"></div>';

            html += '<div class="pA-body">';
            html += '<div class="pA-row"><span class="pA-k">陨落个体</span><span class="pA-v strong">' + (data.name || '未知') + '</span></div>';
            html += '<div class="pA-row"><span class="pA-k">最终等级</span><span class="pA-v">' + (data.level || '未知') + '</span></div>';
            html += '<div class="pA-row"><span class="pA-k">存活时长</span><span class="pA-v">' + (data.duration || '未知') + '</span></div>';
            html += '<div class="pA-row"><span class="pA-k">致死原因</span><span class="pA-v strong">' + (data.cause || '未知') + '</span></div>';
            html += '<div class="pA-row"><span class="pA-k">世界线扰动</span><span class="pA-v dim">' + (data.disturbance || '未对本源产生明显干涉') + '</span></div>';
            html += '</div>';

            if (data.evaluation) {
                html += '<div class="pA-eval">「' + data.evaluation + '」</div>';
            }

            html += '<div class="pA-roll">—— 本源回廊 · 归档 ——</div>';
            html += '</div>';
            return html;
        }

        /* ========== 渲染回溯结算（方案A 卷宗文书） ========== */
        // 判定结果是否视为「成功」：兼容多种措辞（成功/通过/稳定/生效/幸免/免疫/减免）
        function isSuccessResult(text) {
            if (!text) return false;
            if (/失败|未通过|无效|崩解|失效/.test(text)) return false;
            return /成功|通过|稳定|生效|幸免|免疫|减免/.test(text);
        }

        function renderRewind(data) {
            var isSuccess = isSuccessResult(data.result);
            var html = '';

            html += '<div class="pA-panel pA-rewind">';
            html += '<span class="pA-corner tl"></span>';
            html += '<span class="pA-corner tr"></span>';
            html += '<span class="pA-corner bl"></span>';
            html += '<span class="pA-corner br"></span>';
            html += '<div class="pA-seal">溯</div>';

            html += '<div class="pA-head">';
            html += '<div class="pA-code">' + (data.subtitle || '法则干涉: 死亡回溯') + '</div>';
            html += '<div class="pA-title">亡者回廊</div>';
            html += '<div class="pA-sub">REWIND · 回溯卷宗</div>';
            html += '</div>';

            html += '<div class="pA-hairline"></div>';

            html += '<div class="pA-body">';
            html += '<div class="pA-row"><span class="pA-k">触发者</span><span class="pA-v strong">' + (data.trigger || '未知') + '</span></div>';
            html += '<div class="pA-row"><span class="pA-k">创伤记忆</span><span class="pA-v">' + (data.trauma || '未知') + '</span></div>';
