                html += '<div class="pA-row"><span class="pA-k">时间回跃</span><span class="pA-v">' + (data.timeFrom || '???') + ' → ' + (data.timeTo || '???') + '</span></div>';
            }
            if (data.dice) {
                var diceText = data.dice;
                if (data.result) {
                    var resColor = isSuccess ? '#2f8f45' : '#c0392b';
                    diceText += ' <span style="color:' + resColor + ';font-weight:700;">' + data.result + '</span>';
                }
                html += '<div class="pA-row"><span class="pA-k">磨损判定</span><span class="pA-v">' + diceText + '</span></div>';
            }
            if (data.status) {
                html += '<div class="pA-row"><span class="pA-k">状态追加</span><span class="pA-v dim">' + data.status + '</span></div>';
            }
            html += '</div>';

            if (data.result) {
                var evalColor = isSuccess ? '#2f8f45' : '#c0392b';
                var evalText = isSuccess ? '时光让步，亡者重临。' : '时光之锚颤动，回溯受限。';
                html += '<div class="pA-eval" style="border-left-color:' + evalColor + ';">' + evalText + '</div>';
            }

            html += '<div class="pA-roll">—— 本源回廊 · 追索 ——</div>';
            html += '</div>';
            return html;
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('content').innerHTML = '<div class="loading">\u2014 \u65E0\u6CD5\u83B7\u53D6\u6D88\u606F \u2014</div>';
                    return;
                }

                var type = detectType(messageText);

                if (type === 'death') {
                    var deathData = parseDeathReport(messageText);
                    document.getElementById('content').innerHTML = renderDeath(deathData);
