                    var rewindData = parseRewindData(messageText);
                    document.getElementById('content').innerHTML = renderRewind(rewindData);
                } else {
                    document.getElementById('content').innerHTML = '<div class="loading">\u2014 \u672A\u68C0\u6D4B\u5230\u7ED3\u7B97\u6570\u636E \u2014</div>';
                }
            } catch (error) {
                document.getElementById('content').innerHTML = '<div class="loading">\u2014 \u52A0\u8F7D\u5931\u8D25 \u2014</div>';
            }
        }

        $(function() { init(); });
    </script>
